export async function main(type: string, data: any) {
  if (type !== "approval.requested") return null;
  return data?.approval?.id ?? null;
}

import * as wmill from "windmill-client";

const AGENTS: Record<string, string> = { "claude-code": "Claude Code", codex: "Codex", "gemini-cli": "Gemini CLI" };

export async function main(approval: any, review_url = "", slack_resource_path = "", slack_channel = "", teams_team = "", teams_channel = "") {
  const who = approval.os_user ? `${approval.os_user} on ${approval.hostname}` : approval.hostname;
  const message = [
    `Effigent: ${AGENTS[approval.agent] ?? approval.agent} (${who}) is waiting for approval`,
    approval.summary,
    `Why: ${approval.reason}`,
    `Request ${approval.id}${review_url ? ` · ${review_url}` : ""}`,
  ].join("\n");
  if (slack_resource_path && slack_channel) {
    await wmill.requestInteractiveSlackApproval({ slackResourcePath: slack_resource_path, channelId: slack_channel, message });
  }
  if (teams_team && teams_channel) {
    await wmill.requestInteractiveTeamsApproval({ teamName: teams_team, channelName: teams_channel, message });
  }
  const urls = await wmill.getResumeUrls();
  return { message, approval_page: urls.approvalPage };
}

export async function main(resume: any, resumes: any[], approvers: string[]) {
  const err = resume?.error?.name;
  // timed out: do nothing; the request expires in Effigent and the action stays blocked
  if (err && err !== "SuspendedDisapproved") return { decision: "skip" };
  const note = (err ? (resumes ?? []).find((r) => r && !r.error)?.note : resume?.note) ?? "";
  return { decision: err ? "deny" : "approve", approver: (approvers ?? []).join(", "), note };
}
